mapper.update:
update mst_shift
   set shift_nm = #{f.shiftNm}, start_time = #{f.startTime}, end_time = #{f.endTime}, day_offset = #{f.dayOffset},
       break_min = #{f.breakMin}, sort_no = #{f.sortNo}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where shift_id = #{id} and row_ver = #{f.rowVer}

mapper.select:
select q.qual_id, q.qual_cd, q.qual_nm, q.valid_months, q.sort_no, q.use_yn, q.remark, q.row_ver, q.updated_at, q.updated_by, (select count(distinct h.worker_id) from mst_worker_qual h join mst_worker w on w.worker_id = h.worker_id where h.qual_id = q.qual_id and w.use_yn = 'Y' and ) as holder_cnt, (select count(*) from mst_proc_qual_req r where r.qual_id = q.qual_id and r.use_yn = 'Y') as proc_cnt from mst_qual q q.use_yn = #{useYn} order by
q.qual_cd desc q.qual_nm desc q.valid_months desc nulls last holder_cnt desc proc_cnt desc q.sort_no desc ,
q.qual_id limit #{page.size} offset #{page.offset}

select q.qual_id, q.qual_cd, q.qual_nm, q.valid_months, q.sort_no, q.use_yn, q.remark, q.row_ver, q.updated_at,
       q.updated_by, 0 as holder_cnt, 0 as proc_cnt
  from mst_qual q where q.qual_id = #{id}

select q.qual_id, q.qual_cd, q.qual_nm, q.valid_months, q.sort_no, q.use_yn, q.remark, q.row_ver, q.updated_at,
       q.updated_by, 0 as holder_cnt, 0 as proc_cnt
  from mst_qual q where q.qual_cd = #{qualCd}

mapper.update:
update mst_qual
   set qual_nm = #{f.qualNm}, valid_months = #{f.validMonths}, sort_no = #{f.sortNo}, use_yn = #{f.useYn},
       remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where qual_id = #{id} and row_ver = #{f.rowVer}

mapper.select:
select 
  from mst_proc_qual_req r join mst_proc p on p.proc_id = r.proc_id join mst_qual q on q.qual_id = r.qual_id

    r.qual_id = #{qualId}
    and r.proc_id = #{procId}

 order by p.sort_no, p.proc_cd, q.sort_no, q.qual_cd

select 
  from mst_proc_qual_req r join mst_proc p on p.proc_id = r.proc_id join mst_qual q on q.qual_id = r.qual_id
 where r.req_id = #{id}

mapper.update:
update mst_proc_qual_req
   set gate_mode = #{gateMode}, use_yn = #{useYn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where req_id = #{id} and row_ver = #{rowVer}

mapper.select:
select from mst_worker w left join sys_plant pl on pl.plant_cd = w.plant_cd left join sys_user u on u.user_id = w.user_id
w.plant_cd = #{plantCd} and (w.worker_cd ilike #{keywordLike} escape '\' or w.worker_nm ilike #{keywordLike} escape '\' or w.dept_nm ilike #{keywordLike} escape '\') and w.use_yn = #{useYn}
order by w.worker_cd limit 2000

mapper.sql:
from mst_worker w left join sys_plant pl on pl.plant_cd = w.plant_cd left join sys_user u on u.user_id = w.user_id

  w.plant_cd = #{plantCd}
  and (w.worker_cd ilike #{keywordLike} escape '\' or w.worker_nm ilike #{keywordLike} escape '\'
      or w.dept_nm ilike #{keywordLike} escape '\')
  and w.use_yn = #{useYn}

mapper.select:
select 
  from mst_worker w left join sys_plant pl on pl.plant_cd = w.plant_cd left join sys_user u on u.user_id = w.user_id
 where w.worker_id = #{id}

mapper.update:
update mst_worker
   set worker_nm = #{f.workerNm}, plant_cd = #{f.plantCd}, dept_nm = #{f.deptNm}, user_id = #{f.userId},
       use_yn = #{f.useYn}, remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where worker_id = #{id} and row_ver = #{f.rowVer}

update mst_worker set pin_hash = #{pinHash}, pin_fail_cnt = 0, pin_locked_until = null, row_ver = row_ver + 1,
       updated_at = now(), updated_by = #{by}
 where worker_id = #{id} and row_ver = #{rowVer}

mapper.select:
select  from mst_worker_qual h join mst_qual q on q.qual_id = h.qual_id
 where h.worker_id = #{workerId}
 order by q.sort_no, q.qual_cd, h.acquired_on desc, h.wq_id desc

mapper.update:
update mst_worker_qual
   set expires_on = #{f.expiresOn}, revoked_on = #{f.revokedOn}, cert_no = #{f.certNo}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where wq_id = #{id} and row_ver = #{f.rowVer}

mapper.select:
select  from mst_worker_qual h join mst_qual q on q.qual_id = h.qual_id
 where h.worker_id = #{workerId}
   and h.qual_id in #{q}
